import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict(side, price, qty, arrival, active)
    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)
    arrival = 0

    for order in orders:
        arrival += 1
        op = order[0]

        if op == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid]['active'] = False
                del book[oid]
            continue

        if op == 'limit':
            _, oid, side, price, qty = order
        elif op == 'ioc':
            _, oid, side, price, qty = order
        elif op == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                top_price, top_arrival, top_id = heap[0]
                if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if op != 'market' and price < top_price:
                    break
                trade_qty = min(remaining, book[top_id]['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                book[top_id]['qty'] -= trade_qty
                if book[top_id]['qty'] == 0:
                    book[top_id]['active'] = False
                    del book[top_id]
                    heapq.heappop(heap)

            if remaining > 0 and op == 'limit':
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining,
                             'arrival': arrival, 'active': True}
                heapq.heappush(buy_heap, (-price, arrival, oid))

        else:  # side == 'sell'
            heap = buy_heap
            while remaining > 0 and heap:
                neg_price, top_arrival, top_id = heap[0]
                top_price = -neg_price
                if top_id not in book or not book[top_id]['active'] or book[top_id]['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if op != 'market' and price > top_price:
                    break
                trade_qty = min(remaining, book[top_id]['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                book[top_id]['qty'] -= trade_qty
                if book[top_id]['qty'] == 0:
                    book[top_id]['active'] = False
                    del book[top_id]
                    heapq.heappop(heap)

            if remaining > 0 and op == 'limit':
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining,
                             'arrival': arrival, 'active': True}
                heapq.heappush(sell_heap, (price, arrival, oid))

    return trades

